example.code:
// requestReadPixels invokes the callback with a result that is only valid
// for the duration of the callback, so copy the data out before returning.
SKBitmap captured = null;
image.RequestReadPixels(info, srcRect, result => {
    if (result == null)
        return; // the asynchronous read failed
    // ToBitmap makes an owned copy that outlives the callback.
    captured = result.ToBitmap();
});
